import{_ as t,a0 as p,w as o,s as r,I as i,x as n,a1 as l,A as e,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"用 rcm 管理隱藏文件 | LCTT x X-CMD","titleTemplate":false,"description":"用 rcm 管理隱藏文件 | LCTT (201901) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"用 rcm 管理隱藏文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"用 rcm 管理隱藏文件 | LCTT (201901) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201901/20190104 Managing dotfiles with rcm","title":"用 rcm 管理隱藏文件","tag":"201901","desc":""},"relativePath":"201901/20190104 Managing dotfiles with rcm.md","filePath":"[post].md"}'),c={name:"201901/20190104 Managing dotfiles with rcm.md"};function h(g,s,k,m,u,b){const a=p("Link");return o(),r("div",null,[s[24]||(s[24]=i("h1",{id:"用-rcm-管理隱藏文件",tabindex:"-1"},[n("用 rcm 管理隱藏文件 "),i("a",{class:"header-anchor",href:"#用-rcm-管理隱藏文件","aria-label":"Permalink to “用 rcm 管理隱藏文件”"},"​")],-1)),s[25]||(s[25]=i("p",null,[i("img",{src:"https://fedoramagazine.org/wp-content/uploads/2018/12/dotfiles-816x345.jpg",alt:""})],-1)),i("p",null,[s[1]||(s[1]=n("許多 GNU/Linux 程序的一個特點是有個易於編輯的配置文件。幾乎所有常見的自由軟件都將配置設置保存在純文本文件中，通常採用結構化格式，如 JSON、YAML 或",-1)),l(a,{href:"https://en.wikipedia.org/wiki/INI_file"},{default:e(()=>[...s[0]||(s[0]=[n("“類似 ini”",-1)])]),_:1}),s[2]||(s[2]=n(" 的文件中。這些配置文件經常隱藏在用户的主目錄中。但是，基本的 ",-1)),s[3]||(s[3]=i("code",null,"ls",-1)),s[4]||(s[4]=n(" 不會顯示它們。UNIX 標準要求以點開頭的任何文件或目錄名稱都被視為“隱藏”，除非用户特意要求，否則不會列在目錄列表中。例如，要使用 ",-1)),s[5]||(s[5]=i("code",null,"ls",-1)),s[6]||(s[6]=n(" 列出所有文件，要傳遞 ",-1)),s[7]||(s[7]=i("code",null,"-a",-1)),s[8]||(s[8]=n(" 選項。",-1))]),s[26]||(s[26]=d(`<p>隨着時間的推移，這些配置文件會有很多定製配置，管理它們變得越來越具有挑戰性。不僅如此，在多台計算機之間保持同步是大型組織所面臨的共同挑戰。最後，許多用户也對其獨特的配置感到自豪，並希望以簡單的方式與朋友分享。這就是用到 rcm 介入的地方。</p><p>rcm 是一個 “rc” 文件管理套件（“rc” 是命名配置文件的另一種約定，它已被某些 GNU/Linux 程序採用，如 <code>screen</code> 或 <code>bash</code>）。 rcm 提供了一套命令來管理和列出它跟蹤的文件。使用 <code>dnf</code> 安裝 rcm。</p><h3 id="開始使用" tabindex="-1">開始使用 <a class="header-anchor" href="#開始使用" aria-label="Permalink to “開始使用”">​</a></h3><p>默認情況下，rcm 使用 <code>~/.dotfiles</code> 來存儲它管理的所有隱藏文件。一個被管理的隱藏文件實際保存在 <code>~/.dotfiles</code> 目錄中，而它的符號鏈接會放在文件原本的位置。例如，如果 <code>~/.bashrc</code> 由 rcm 所管理，那麼詳細列表將如下所示。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[link@localhost ~]$ ls -l ~/.bashrc</span></span>
<span class="line"><span>lrwxrwxrwx. 1 link link 27 Dec 16 05:19 .bashrc -&gt; /home/link/.dotfiles/bashrc</span></span>
<span class="line"><span>[link@localhost ~]$</span></span></code></pre></div><p>rcm 包含 4 個命令：</p><ul><li><code>mkrc</code> – 將文件轉換為由 rcm 管理的隱藏文件</li><li><code>lsrc</code> – 列出由 rcm 管理的文件</li><li><code>rcup</code> – 同步由 rcm 管理的隱藏文件</li><li><code>rcdn</code> – 刪除 rcm 管理的所有符號鏈接</li></ul><h3 id="在兩台計算機上共享-bashrc" tabindex="-1">在兩台計算機上共享 bashrc <a class="header-anchor" href="#在兩台計算機上共享-bashrc" aria-label="Permalink to “在兩台計算機上共享 bashrc”">​</a></h3><p>如今用户在多台計算機上擁有 shell 帳户並不罕見。在這些計算機之間同步隱藏文件可能是一個挑戰。這裏將提供一種可能的解決方案，僅使用 rcm 和 git。</p><p>首先使用 <code>mkrc</code> 將文件轉換成由 rcm 管理的文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[link@localhost ~]$ mkrc -v ~/.bashrc</span></span>
<span class="line"><span>Moving...</span></span>
<span class="line"><span>&#39;/home/link/.bashrc&#39; -&gt; &#39;/home/link/.dotfiles/bashrc&#39;</span></span>
<span class="line"><span>Linking...</span></span>
<span class="line"><span>&#39;/home/link/.dotfiles/bashrc&#39; -&gt; &#39;/home/link/.bashrc&#39;</span></span>
<span class="line"><span>[link@localhost ~]$</span></span></code></pre></div><p>接下來使用 <code>lsrc</code> 驗證列表是否正確。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[link@localhost ~]$ lsrc</span></span>
<span class="line"><span>/home/link/.bashrc:/home/link/.dotfiles/bashrc</span></span>
<span class="line"><span>[link@localhost ~]$</span></span></code></pre></div><p>現在在 <code>~/.dotfiles</code> 中創建一個 git 倉庫，並使用你選擇的 git 倉庫託管設置一個遠程倉庫。提交 <code>bashrc</code> 文件並推送一個新分支。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[link@localhost ~]$ cd ~/.dotfiles</span></span>
<span class="line"><span>[link@localhost .dotfiles]$ git init</span></span>
<span class="line"><span>Initialized empty Git repository in /home/link/.dotfiles/.git/</span></span>
<span class="line"><span>[link@localhost .dotfiles]$ git remote add origin git@github.com:linkdupont/dotfiles.git</span></span>
<span class="line"><span>[link@localhost .dotfiles]$ git add bashrc</span></span>
<span class="line"><span>[link@localhost .dotfiles]$ git commit -m &quot;initial commit&quot;</span></span>
<span class="line"><span>[master (root-commit) b54406b] initial commit</span></span>
<span class="line"><span>1 file changed, 15 insertions(+)</span></span>
<span class="line"><span>create mode 100644 bashrc</span></span>
<span class="line"><span>[link@localhost .dotfiles]$ git push -u origin master</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>[link@localhost .dotfiles]$</span></span></code></pre></div><p>在第二台機器上，克隆這個倉庫到 <code>~/.dotfiles</code> 中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[link@remotehost ~]$ git clone git@github.com:linkdupont/dotfiles.git ~/.dotfiles</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>[link@remotehost ~]$</span></span></code></pre></div><p>現在使用 <code>rcup</code> 更新受 rcm 管理的符號鏈接。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[link@remotehost ~]$ rcup -v</span></span>
<span class="line"><span>replacing identical but unlinked /home/link/.bashrc</span></span>
<span class="line"><span>removed &#39;/home/link/.bashrc&#39;</span></span>
<span class="line"><span>&#39;/home/link/.dotfiles/bashrc&#39; -&gt; &#39;/home/link/.bashrc&#39;</span></span>
<span class="line"><span>[link@remotehost ~]$</span></span></code></pre></div><p>覆蓋現有的 <code>~/.bashrc</code>（如果存在）並重啓 shell。</p><p>就是這些了！指定主機選項 （<code>-o</code>） 是對上面這種情況的有用補充。如往常一樣，請閲讀手冊頁。它們包含了很多示例命令。</p><hr>`,22)),i("p",null,[s[10]||(s[10]=n("via: ",-1)),l(a,{href:"https://fedoramagazine.org/managing-dotfiles-rcm/"},{default:e(()=>[...s[9]||(s[9]=[n("https://fedoramagazine.org/managing-dotfiles-rcm/",-1)])]),_:1})]),i("p",null,[s[15]||(s[15]=n("作者：",-1)),l(a,{href:"https://fedoramagazine.org/author/linkdupont/"},{default:e(()=>[...s[11]||(s[11]=[n("Link Dupont",-1)])]),_:1}),s[16]||(s[16]=n(" 選題：",-1)),l(a,{href:"https://github.com/lujun9972"},{default:e(()=>[...s[12]||(s[12]=[n("lujun9972",-1)])]),_:1}),s[17]||(s[17]=n(" 譯者：",-1)),l(a,{href:"https://github.com/geekpi"},{default:e(()=>[...s[13]||(s[13]=[n("geekpi",-1)])]),_:1}),s[18]||(s[18]=n(" 校對：",-1)),l(a,{href:"https://github.com/wxy"},{default:e(()=>[...s[14]||(s[14]=[n("wxy",-1)])]),_:1})]),i("p",null,[s[21]||(s[21]=n("本文由 ",-1)),l(a,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[19]||(s[19]=[n("LCTT",-1)])]),_:1}),s[22]||(s[22]=n(" 原創編譯，",-1)),l(a,{href:"https://linux.cn/"},{default:e(()=>[...s[20]||(s[20]=[n("Linux中國",-1)])]),_:1}),s[23]||(s[23]=n(" 榮譽推出",-1))])])}const T=t(c,[["render",h]]);export{C as __pageData,T as default};
